import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Introduzione","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/a_algebra/af/afccha.md","filePath":"lezioni/a_algebra/af/afccha.md"}`),a={name:`lezioni/a_algebra/af/afccha.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="introduzione" tabindex="-1">Introduzione <a class="header-anchor" href="#introduzione" aria-label="Permalink to “Introduzione”">​</a></h1><blockquote><p>Come argomento è &quot;trasversale&quot;; cioè, partendo dalle equazioni di secondo grado, può essere applicato a vari problemi di diversi rami della matematica e quindi richiede conoscenze di geometria analitica, di algebra, di trigonometria.</p><p>Sviluppo qui le varie applicazioni senza frammentarle nelle varie discipline; naturalmente, per alcuni argomenti, dovrai prima aver studiato la parte di teoria relativa: in cima ad ogni parte indicherò quali sono gli argomenti da sapere (con una parolona: prerequisiti) per seguire il ragionamento.</p></blockquote><p>Un&#39;<strong>equazione con parametro</strong> è un&#39;equazione in cui compare una lettera: al variare della lettera varierà il valore delle soluzioni.</p><p>La <strong>discussione</strong> di un&#39;equazione con parametro è il confrontare le possibili soluzioni con uno o più valori assegnati in modo da controllare per quali valori del parametro tali soluzioni sono comprese in prefissati intervalli;</p><p>Questo serve quando fai un problema e le soluzioni che cerchi debbono rispettare certi limiti come ad esempio essere maggiori di un dato numero altrimenti un radicale non ti dà soluzioni, oppure comprese in un intervallo in modo che un punto di una figura geometrica non esca dalla figura stessa, eccetera. Ne vedrai esempi nella discussione di un problema.</p>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};